// The source is shared by visits of the same file. Decoding may settle later.
export function watchTransferProgress(feed, receive, record, options = {}) {
  let active = true;
  const listener = event => {
    if (!active || (options.accept && !options.accept())) return;
    const deliver = frame => { record(frame); receive(frame); };
    const decoded = feed.decode(event.detail);
    if (decoded && typeof decoded.then === "function") decoded.then(deliver);
    else deliver(decoded);
  };
  feed.target.addEventListener("progress", listener);
  const stop = () => {
    if (!active) return;
    active = false;
    feed.target.removeEventListener("progress", listener);
  };
  // Publish cleanup before start can synchronously call back into the workspace.
  if (options.onReady) options.onReady(stop);
  feed.start();
  return stop;
}

